import json
from pathlib import Path
TEMPLATE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#162c44;font:15px system-ui,-apple-system,Segoe UI,sans-serif}header{background:#102b40;color:white;padding:34px max(5vw,20px)}header small{letter-spacing:2px;color:#6ed3c7}h1{font-size:32px;margin:10px 0}header p{color:#bdd0dd;margin:5px 0}main{max-width:1320px;margin:auto;padding:25px}section{margin-bottom:20px}.toolbar{display:flex;gap:14px;align-items:end;flex-wrap:wrap}label{display:grid;gap:7px;font-size:12px;font-weight:650;color:#52677b}select,button{border:1px solid #c9d5df;background:white;border-radius:8px;padding:10px 16px;color:#16324a;font:inherit}button{cursor:pointer;background:#147b78;color:white;border:0}button.secondary{background:white;color:#16324a;border:1px solid #c9d5df}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.kpi,.panel{background:white;border:1px solid #e0e7ed;border-radius:12px;padding:22px}.kpi small{color:#587084;font-size:12px}.kpi strong{display:block;font-size:28px;margin-top:10px;letter-spacing:-1px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel h2{font-size:17px;margin:0 0 20px}.bar{display:grid;grid-template-columns:128px 1fr 90px;gap:10px;align-items:center;margin:11px 0;font-size:12px}.track{height:16px;background:#edf3f7;border-radius:3px}.fill{height:100%;background:#148982;border-radius:3px}.num{text-align:right;font-variant-numeric:tabular-nums}.notes{border-left:4px solid #148982;background:#e6f2f0;padding:18px 22px}.notes li{margin:8px 0}.notes strong{display:block;margin-bottom:8px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid #e7edf2}th{color:#577184}.scroll{overflow:auto}footer{font-size:12px;color:#657c8e;padding:12px 0 25px;line-height:1.7}svg{width:100%;height:265px}.empty{padding:40px;color:#687f92} @media(max-width:750px){.grid{grid-template-columns:1fr}.kpis{grid-template-columns:1fr 1fr}.kpi strong{font-size:22px}h1{font-size:26px}.bar{grid-template-columns:95px 1fr 75px}}
</style></head><body><header><small>MOHAMMAD ALMEJNAH · ANALYTICS PORTFOLIO</small><h1>__TITLE__</h1><p id="subtitle"></p></header><main><section class="toolbar"><label id="label1">Filter<select id="filter1"></select></label><label id="label2">Filter<select id="filter2"></select></label><button id="reset" class="secondary">Reset filters</button><button id="export">Export filtered CSV</button><span id="count"></span></section><section id="kpis" class="kpis"></section><section class="grid"><article class="panel"><h2 id="chart1title"></h2><div id="chart1"></div></article><article class="panel"><h2 id="chart2title"></h2><div id="chart2"></div></article></section><section class="notes"><strong>Findings and interpretation · Full dataset</strong><ul id="insights"></ul></section><section class="panel"><h2 id="tabletitle">Selected data</h2><div class="scroll"><table id="table"></table></div></section><footer>Portfolio simulation · AI-assisted implementation · Figures are calculated from the documented source snapshots.<br>This is a self-contained web preview, not a Power BI Service publication. Power BI project files are supplied separately. No measured commercial impact is claimed.</footer></main><script>
const P=__PAYLOAD__,D=P.data,$=x=>document.getElementById(x),sum=(a,k)=>a.reduce((s,r)=>s+Number(r[k]||0),0),uniq=(a,k)=>new Set(a.map(r=>r[k])).size;
const fmt=(v,mode='number')=>mode==='pct'?(v*100).toFixed(1)+'%':mode==='money'?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v):new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(v);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=P.kind==='sales'?['year','region']:P.kind==='rfm'?['segment','r_score']:['year','region'];
$('subtitle').textContent=P.subtitle;
fields.forEach((key,i)=>{const el=$('filter'+(i+1));$('label'+(i+1)).firstChild.textContent=key.replaceAll('_',' ').toUpperCase();el.innerHTML='<option value="">All</option>'+[...new Set(D.map(r=>r[key]))].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true})).map(x=>'<option>'+esc(x)+'</option>').join('');el.onchange=render;});
if(P.kind==='saudi')$('filter1').value='2022';
let current=[];
function group(rows,key,value){const m={};rows.forEach(r=>m[r[key]]=(m[r[key]]||0)+Number(r[value]||0));return Object.entries(m).map(([label,value])=>({label,value}));}
function bars(id,arr,mode='number'){const max=Math.max(...arr.map(x=>Math.abs(x.value)),1);$(id).innerHTML=arr.map(x=>'<div class="bar"><span>'+esc(x.label)+'</span><div class="track"><div class="fill" style="width:'+Math.max(.4,Math.abs(x.value)/max*100)+'%;background:'+(x.value<0?'#bd5353':'#148982')+'"></div></div><span class="num">'+fmt(x.value,mode)+'</span></div>').join('')||'<p class="empty">No records</p>';}
function line(id,arr){if(!arr.length){$(id).innerHTML='<p class="empty">No records</p>';return;}const W=550,H=260,left=50,top=20,bottom=45,max=Math.max(...arr.map(r=>r.value),1);const points=arr.map((r,i)=>[left+i*(W-left-15)/Math.max(arr.length-1,1),H-bottom-r.value/max*(H-top-bottom)]);let s='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Time trend">';[0,.5,1].forEach(f=>{let y=H-bottom-f*(H-top-bottom);s+='<line x1="'+left+'" y1="'+y+'" x2="'+W+'" y2="'+y+'" stroke="#e1e8ed"/><text x="2" y="'+(y+4)+'" fill="#657c8e" font-size="10">'+fmt(max*f/1000)+'k</text>';});s+='<polyline fill="none" stroke="#148982" stroke-width="3" points="'+points.map(p=>p.join(',')).join(' ')+'"/>';arr.forEach((r,i)=>{if(i%Math.max(1,Math.floor(arr.length/5))===0||i===arr.length-1)s+='<text x="'+points[i][0]+'" y="'+(H-15)+'" text-anchor="middle" fill="#657c8e" font-size="10">'+esc(r.label)+'</text>';});$(id).innerHTML=s+'</svg>';}
function table(rows,cols){$('table').innerHTML='<thead><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,15).map(r=>'<tr>'+cols.map(c=>'<td>'+esc(typeof r[c]==='number'?fmt(r[c]):r[c])+'</td>').join('')+'</tr>').join('')+'</tbody>';}
function render(){current=D.filter(r=>fields.every((k,i)=>!$('filter'+(i+1)).value||String(r[k])===$('filter'+(i+1)).value));let k=[];
if(P.kind==='sales'){let s=sum(current,'sales'),p=sum(current,'profit');k=[['Sales',s,'money'],['Profit',p,'money'],['Profit margin',s?p/s:0,'pct'],['Distinct orders',uniq(current,'order_id')]];$('chart1title').textContent='Monthly sales';line('chart1',group(current,'month','sales').sort((a,b)=>a.label.localeCompare(b.label)));$('chart2title').textContent='Profit by product subcategory';bars('chart2',group(current,'sub_category','profit').sort((a,b)=>a.value-b.value),'money');table(current,['order_id','order_date','region','sub_category','sales','profit']);}
else if(P.kind==='rfm'){k=[['Customers',current.length],['Historical revenue',sum(current,'monetary'),'money'],['Average recency · days',current.length?sum(current,'recency_days')/current.length:0],['Average orders',current.length?sum(current,'frequency')/current.length:0]];let c={};current.forEach(r=>c[r.segment]=(c[r.segment]||0)+1);$('chart1title').textContent='Customers by segment';bars('chart1',Object.entries(c).map(([label,value])=>({label,value})));$('chart2title').textContent='Revenue by segment';bars('chart2',group(current,'segment','monetary').sort((a,b)=>b.value-a.value),'money');table(current.sort((a,b)=>b.monetary-a.monetary),['customer_id','segment','recency_days','frequency','monetary']);}
else{let year=Math.max(...current.map(r=>r.year),0),last=current.filter(r=>r.year===year),pop=sum(last,'population');let reg=$('filter2').value;let base=D.filter(r=>r.year===2010&&(!reg||r.region===reg)),p0=sum(base,'population');k=[['Population · '+year,pop],['Regions',uniq(last,'region')],['Growth since 2010',p0?pop/p0-1:0,'pct'],['Region-year records',current.length]];$('chart1title').textContent='Regional population · '+year;bars('chart1',group(last,'region','population').sort((a,b)=>b.value-a.value));$('chart2title').textContent='Historical trend · selected region (all years)';line('chart2',group(D.filter(r=>!reg||r.region===reg),'year','population').sort((a,b)=>Number(a.label)-Number(b.label)));table(current,['year','region','population']);}
$('kpis').innerHTML=k.map(([n,v,m])=>'<div class="kpi"><small>'+esc(n)+'</small><strong>'+fmt(v,m)+'</strong></div>').join('');$('count').textContent=current.length.toLocaleString()+' selected records';$('insights').innerHTML=P.insights.map(x=>'<li>'+esc(x)+'</li>').join('');}
$('reset').onclick=()=>{$('filter1').value=P.kind==='saudi'?'2022':'';$('filter2').value='';render();};$('export').onclick=()=>{if(!current.length)return;let keys=Object.keys(current[0]),quote=x=>'"'+String(x??'').replaceAll('"','""')+'"',csv=[keys.map(quote).join(','),...current.map(r=>keys.map(k=>quote(r[k])).join(','))].join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='filtered_data.csv';a.click();URL.revokeObjectURL(a.href);};render();
</script></body></html>'''
def build(root):
 root=Path(root);p=json.loads((root/'outputs/dashboard_data.json').read_text());(root/'dashboard.html').write_text(TEMPLATE.replace('__TITLE__',p['title']).replace('__PAYLOAD__',json.dumps(p,ensure_ascii=False).replace('</','<\\/')))
